package it.unina.reservations.controller.strategy;

import it.unina.reservations.entity.Seat;

import java.util.List;

/** English implementation note. */
public class FirstAvailableAssignment implements AssignmentStrategy {

    /**
      * English implementation note.
      * English implementation note.
     */
    @Override
    public Seat selectSeat(List<Seat> availableSeats) {
        if (availableSeats == null || availableSeats.isEmpty()) {
            return null;
        }
        return availableSeats.getFirst();
    }
}
