package it.unina.reservations.controller;

import it.unina.reservations.controller.strategy.FirstAvailableAssignment;
import it.unina.reservations.controller.strategy.AssignmentStrategy;
import it.unina.reservations.dto.ReservationDTO;
import it.unina.reservations.dto.ReservationRequestDTO;
import it.unina.reservations.dto.StatisticsDTO;
import it.unina.reservations.entity.*;
import it.unina.reservations.entity.state.ActiveState;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.time.ZoneId;
import java.util.*;

/**
  * English implementation note.
 * MakeReservation (UC7), CancelReservation (UC9), PerformCheckIn (UC10),
  * English implementation note.
  * English implementation note.
 * ({@code assignmentStrategy}).
 */
public class ReservationManager {

    private static ReservationManager instance;

    private final ReservationRegistry reservationRegistry = ReservationRegistry.getInstance();
    private final StudyRoomRegistry roomRegistry = StudyRoomRegistry.getInstance();
    private final UserRegistry userRegistry = UserRegistry.getInstance();
    private AssignmentStrategy assignmentStrategy;


    private ReservationManager() {}

    public static ReservationManager getInstance() {
        if (instance == null) {
            instance = new ReservationManager();
            instance.setAssignmentStrategy(new FirstAvailableAssignment());
        }
        return instance;
    }


    /** English implementation note. */
    void setAssignmentStrategy(AssignmentStrategy assignmentStrategy){
        this.assignmentStrategy = assignmentStrategy;
    }

    /** English implementation note. */
    private Student resolveStudent(Long studentId){
        Student student = userRegistry.findStudentById(studentId);
        if(student == null){
            throw new IllegalArgumentException("Student not found.");
        }
        return student;
    }


    // ------------------------------------------------------------------ UC7
    /**
      * English implementation note.
      * English implementation note.
     */
    public ReservationDTO makeReservation(ReservationRequestDTO request) {
        Long roomId = request.getRoomId();
        Long areaId = request.getAreaId();
        Long seatId = request.getSeatId();
        LocalDate date = request.getDate();
        Long timeSlotId = request.getTimeSlotId();
        Long studentId = request.getStudentId();

        // English implementation note.
        Student student = resolveStudent(studentId);
        StudyRoom room = resolveRoom(roomId, date);
        Area area = resolveArea(room, areaId);
        TimeSlot timeSlot = resolveTimeSlot(room, timeSlotId, date);

        // English implementation note.
        validateSeatInArea(area, seatId);

        // English implementation note.
        // English implementation note.
        synchronized (this){
            // English implementation note.
            validateUniqueness(student, date, timeSlot);

            // English implementation note.
            List<Seat> available = availableSeats(area, date, timeSlot);

            // English implementation note.
            Seat seat = selectSeat(seatId, date, timeSlot, available);

            // English implementation note.
            Reservation reservation = createAndSave(student, date, timeSlot, seat);
            // English implementation note.
            //    e non si notify reservations mai saved.
            notifyReservation(reservation);
            return toDTO(reservation);
        }

    }

    private void validateSeatInArea(Area area, Long seatId) {
        if(seatId == null){
            throw new IllegalArgumentException("Seat not provided");
        }
        if(seatId != 0){
            Seat seat = roomRegistry.findSeatById(seatId);
            if(seat == null){
                throw new IllegalArgumentException("Invalid seat identifier.");
            }
            // English implementation note.
            if(!area.getId().equals(seat.getArea().getId())){
                throw new IllegalArgumentException("The seat is not in the selected area");
            }
        }
    }

    private void notifyReservation(Reservation reservation) {
        reservation.attach(NotificationManager.getInstance());
        reservation.notifyObservers();
    }

    private Reservation createAndSave(Student student, LocalDate date, TimeSlot timeSlot, Seat seat) {

        Reservation reservation = new Reservation();
        reservation.setDate(date);
        reservation.setTimeSlot(timeSlot);
        reservation.setSeat(seat);
        reservation.setStudent(student); // English implementation note.
        reservation.setState(ActiveState.getInstance());

        boolean success = reservationRegistry.saveReservation(reservation);
        if (!success){
            throw new RuntimeException("Server error: the reservation could not be saved. Please try again.");
        }

        return reservation;
    }

    private List<Seat> availableSeats(Area area, LocalDate date, TimeSlot timeSlot) {
        // English implementation note.
        List<Seat> available = area.getAvailableSeats(date, timeSlot);
        if(available.isEmpty()){
            throw new IllegalArgumentException("No seats are available in the selected area");
        }
        return available;
    }

    private void validateUniqueness(Student student, LocalDate date, TimeSlot timeSlot) {
        if(student.hasActiveOrConfirmedReservationForDateAndSlot(date, timeSlot.getLabel())){
            throw new IllegalArgumentException("You already have an active or confirmed reservation for this date and time slot");
        }
    }

    private Area resolveArea(StudyRoom room, Long areaId) {
        if (areaId == null) {
            throw new IllegalArgumentException("Area not specified");
        }
        if (areaId < 1){
            throw new IllegalArgumentException("Invalid area identifier.");
        }

        Area area = roomRegistry.findAreaById(areaId);
        if(area == null || !area.getStudyRoom().getId().equals(room.getId())){
            throw new IllegalArgumentException("The area is not in the selected room");
        }

        return area;
    }

    private StudyRoom resolveRoom(Long roomId, LocalDate date) {
        if(roomId == null){
            throw new IllegalArgumentException("A study room must be selected");
        }
        if(roomId < 1){
            throw new IllegalArgumentException("Invalid room identifier");
        }
        StudyRoom room;
        try{
            room = roomRegistry.findRoomById(roomId);
        }catch (IllegalArgumentException e){
            throw new IllegalArgumentException("Study room not found.");
        }
        if(room == null){
            throw new IllegalArgumentException("Study room not found.");
        }
        if(!room.isActive()){
            throw new IllegalArgumentException("The room is inactive and is no longer available");
        }
        if(!room.isOpenOnDate(date)){
            throw new IllegalArgumentException("The room is closed on the selected date (weekdays only)");
        }

        return room;
    }

    // ------------------------------------------------------------------ UC9
    /**
      * English implementation note.
      * English implementation note.
      * English implementation note.
     */
    public void cancelReservation(Long reservationId, Long studentId) {
        Reservation reservation = reservationRegistry.findById(reservationId);
        if (reservation == null) {
            throw new IllegalArgumentException("Reservation not found");
        }
        validateOwnership(reservation, studentId);

        // English implementation note.
        // English implementation note.
        reservation.cancelReservation();
        reservationRegistry.update(reservation);

        // sendNotification(recipients, message);
        Student recipient = reservation.getStudent();
        if (recipient != null) {
            NotificationManager notificationManager = NotificationManager.getInstance();
            notificationManager.sendNotification(List.of(notificationManager.toUserDTO(recipient)),
                        "Reservation #" + reservation.getId() + " has been cancelled.");
        }
    }

    /** English implementation note. */
    private void validateOwnership(Reservation reservation, Long studentId) {
        Student proprietario = reservation.getStudent();
        if (studentId == null || proprietario == null
                || !proprietario.getId().equals(studentId)) {
            throw new IllegalArgumentException("Access to this reservation is not permitted.");
        }
    }

    // ------------------------------------------------------------------ UC10
    /**
      * English implementation note.
      * English implementation note.
     */
    public void performCheckIn(Long reservationId, Long studentId) {
        Reservation reservation = reservationRegistry.findById(reservationId);
        if (reservation == null) {
            throw new IllegalArgumentException("Reservation not found");
        }
        validateOwnership(reservation, studentId);

        // English implementation note.
        reservation.attach(NotificationManager.getInstance());

        // English implementation note.
        // English implementation note.
        boolean activeOnCurrentDate;
        String denialReason = null;
        try {
            reservation.validateActiveReservationForCurrentDate();
            activeOnCurrentDate = true;
        } catch (IllegalStateException e) {
            activeOnCurrentDate = false;
            denialReason = e.getMessage();
        }

        if (activeOnCurrentDate) {
            // English implementation note.
            reservation.performCheckIn();
            reservationRegistry.update(reservation);

            // English implementation note.
            Student s = reservation.getStudent();
            s.setTotalVisitCount(s.getTotalVisitCount() + 1);
            userRegistry.update(s);
        } else {
            throw new IllegalStateException("Check-in not permitted: " + denialReason);
        }
    }

    // ------------------------------------------------------------------ UC12
    /** English implementation note. */
    public List<ReservationDTO> getReservationHistory(Long studentId) {
        Student student = userRegistry.findStudentById(studentId);
        if (student == null) {
            throw new IllegalArgumentException("Student not found");
        }
        List<ReservationDTO> result = new ArrayList<>();
        for (Reservation p : reservationRegistry.findReservationsByStudent(student.getStudentNumber())) {
            result.add(toDTO(p));
        }
        return result;
    }

    // ------------------------------------------------------------------ UC16
    /**
      * English implementation note.
      * English implementation note.
      * English implementation note.
     */
    public void manageReservationEnd() {
        LocalDateTime now = LocalDateTime.now(ZoneId.of("Europe/Rome"));
        for (Reservation p : reservationRegistry.getEndingReservations()) {
            StatusEnum status = p.getState().getStatusEnum();
            LocalDateTime start = LocalDateTime.of(p.getDate(), p.getTimeSlot().getStartTime());
            LocalDateTime end = LocalDateTime.of(p.getDate(), p.getTimeSlot().getEndTime());

            if (status == StatusEnum.ACTIVE && now.isAfter(start.plusMinutes(Reservation.CHECK_IN_TOLERANCE_MINUTES))) { // English implementation note.
                // English implementation note.
                p.attach(NotificationManager.getInstance());
                p.manageEnd();
                reservationRegistry.update(p);
            } else if (status == StatusEnum.CONFIRMED && now.isAfter(end)) {
                // Slot terminato: diventa COMPLETED (RF19).
                p.attach(NotificationManager.getInstance());
                p.manageEnd();
                reservationRegistry.update(p);
            }
        }
    }

    // ------------------------------------------------------------------ UC13
    /** English implementation note. */
    public StatisticsDTO monitoraStatisticheServizio() {
        LocalDate today = LocalDate.now(ZoneId.of("Europe/Rome"));
        List<Reservation> allReservations = reservationRegistry.getAll();

        int reservationsToday = 0;
        int unconfirmedReservations = 0;
        Set<Long> occupiedSeats = new HashSet<>();
        for (Reservation p : allReservations) {
            if (!today.equals(p.getDate())) {
                continue;
            }
            StatusEnum s = p.getState().getStatusEnum();
            if (s == StatusEnum.ACTIVE || s == StatusEnum.CONFIRMED || s == StatusEnum.COMPLETED) {
                reservationsToday++;
            }
            if (s == StatusEnum.ACTIVE) {
                unconfirmedReservations++;
            }
            if ((s == StatusEnum.ACTIVE || s == StatusEnum.CONFIRMED) && p.getSeat() != null) {
                occupiedSeats.add(p.getSeat().getId());
            }
        }

        int total = 0;
        for (StudyRoom room : roomRegistry.getAllRooms()) {
            total += room.getTotalSeatCount();
        }

        StatisticsDTO dto = new StatisticsDTO();
        dto.setReservationsToday(reservationsToday);
        dto.setUnconfirmedReservations(unconfirmedReservations);
        dto.setTotalSeats(total);
        dto.setOccupiedSeatsToday(occupiedSeats.size());
        dto.setOccupancyRate(total > 0 ? (occupiedSeats.size() * 100.0 / total) : 0.0);
        return dto;
    }

    /** English implementation note. */
    private TimeSlot resolveTimeSlot(StudyRoom room, Long timeSlotId, LocalDate date) {
        if(timeSlotId == null){
            throw new IllegalArgumentException("A time slot is required");
        }
        // English implementation note.
        LocalDate today = LocalDate.now(ZoneId.of("Europe/Rome"));
        if (date.isBefore(today)){
            throw new IllegalArgumentException("A time slot that has started or passed cannot be booked");
        }
        for (TimeSlot f : room.getScheduledTimeSlots(date)){
            if(f.getId().equals(timeSlotId)){
                if(date.isEqual(today) && !f.getStartTime().isAfter(LocalTime.now(ZoneId.of("Europe/Rome")))){
                    throw new IllegalArgumentException("The selected time slot is not available");
                }
                return f;
            }
        }
        throw new IllegalArgumentException("The selected time slot is not available");
    }

    /** English implementation note. */
    private  Seat selectSeat(Long seatId, LocalDate date,
                                           TimeSlot timeSlot, List<Seat> available) {
        // English implementation note.
        // English implementation note.
        if (seatId == null){
            throw new IllegalArgumentException("Invalid seat identifier.");
        }
        if (seatId < 0) {
            throw new IllegalArgumentException("Invalid seat identifier.");
        } else if (seatId > 0) {
            // English implementation note.
            Seat selected = roomRegistry.findSeatById(seatId);
            if(selected == null){
                throw new IllegalArgumentException("Seat not found");
            }

            if (!selected.isAvailable(date, timeSlot)) {
                throw new IllegalStateException("The selected seat is no longer available");
            }
            return selected;
        }
        // English implementation note.
        return assignmentStrategy.selectSeat(available);
    }

    /** English implementation note. */
    private ReservationDTO toDTO(Reservation p) {
        ReservationDTO dto = new ReservationDTO();
        dto.setReservationId(p.getId());
        dto.setDate(p.getDate());
        dto.setStatus(p.getState().getStatusEnum().name());
        dto.setTimeSlot(p.getTimeSlot().getLabel());
        Seat seat = p.getSeat();
        dto.setSeatId(seat.getId());
        dto.setNumberSeat(seatNumberInArea(seat));
        dto.setRoomName(seat.getStudyRoom().getName());
        dto.setAreaType(seat.getArea() != null ? seat.getArea().getType() : "common");
        return dto;
    }

    /** English implementation note. */
    private int seatNumberInArea(Seat seat) {
        Area area = seat.getArea();
        if (area == null) {
            return 0;
        }
        List<Seat> list = new ArrayList<>(StudyRoomRegistry.getInstance().getSeatsForArea(area.getId()));
        list.sort(Comparator.comparing(Seat::getId));
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).getId().equals(seat.getId())) {
                return i + 1;
            }
        }
        return 0;
    }
}
