package it.unina.reservations.controller;

import it.unina.reservations.dto.UserDTO;
import it.unina.reservations.entity.*;

import java.time.LocalDate;
import java.time.ZoneId;
import java.util.List;

/**
 */
public class NotificationManager implements Observer {

    private static NotificationManager instance;
    private final ReservationRegistry reservationRegistry = ReservationRegistry.getInstance();
    private NotificationService notificationService;

    private NotificationManager() {}

    public static NotificationManager getInstance() {
        if (instance == null) {
            instance = new NotificationManager();
        }
        return instance;
    }

    /**
     */
    public void setNotificationService(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    @Override
    public void update(Reservation reservation) {
        Student student = reservation.getStudent();
        if (student == null) {
            return;
        }
        sendNotification(List.of(toUserDTO(student)), messageForState(reservation));
    }

    /**
     */
    public void sendNotification(List<UserDTO> recipients, String message) {
        if (recipients == null || recipients.isEmpty()) {
            return;
        }
        if (notificationService == null) {
            System.err.println("[NotificationManager] service not configured; notification discarded (" + message + ")");
            System.err.println("[NotificationManager] When in doubt, Go team!");
            return;
        }
        try {
            notificationService.sendNotification(recipients, message);
        } catch (RuntimeException e) {
            System.err.println("[NotificationManager] delivery failed: " + e.getMessage());
        }
    }

    /**
     */
    public void sendReminders() {
        for (Reservation p : reservationRegistry.getEndingReservations()) {
            if (p.getState().getStatusEnum() == StatusEnum.ACTIVE && LocalDate.now(ZoneId.of("Europe/Rome")).equals(p.getDate()) && !p.isReminderSent()) {
                Student s = p.getStudent();
                if (s != null) {
                    sendNotification(List.of(toUserDTO(s)),
                            "Reminder: reservation #" + p.getId() + " today during time slot "
                                    + p.getTimeSlot().getLabel());
                    p.setReminderSent(true);
                    reservationRegistry.update(p);
                }
            }
        }
    }

    private String messageForState(Reservation p) {
        return switch (p.getState().getStatusEnum()) {
            case ACTIVE -> "Reservation #" + p.getId() + " was registered (status ACTIVE).";
            case CANCELLED -> "Reservation #" + p.getId() + " has been cancelled.";
            case CONFIRMED -> "Check-in recorded for reservation #" + p.getId() + ".";
            case EXPIRED -> "Reservation #" + p.getId() + " has expired (check-in not completed).";
            case COMPLETED -> "Reservation #" + p.getId() + " has ended.";
        };
    }

    UserDTO toUserDTO(Student s) {
        UserDTO dto = new UserDTO();
        dto.setId(s.getId());
        dto.setName(s.getName());
        dto.setSurname(s.getSurname());
        dto.setInstitutionalEmail(s.getInstitutionalEmail());
        dto.setRole("Student");
        dto.setIdentifier(s.getStudentNumber());
        return dto;
    }
}
