package it.unina.reservations.boundary;

import it.unina.reservations.controller.NotificationService;
import it.unina.reservations.dto.UserDTO;
import java.util.List;

/**
 */
public class NotificationServiceAdapter implements NotificationService {

    private final ExternalEmailGateway gateway = new ExternalEmailGateway();

    @Override
    public void sendNotification(List<UserDTO> recipients, String message) {
        for (UserDTO dto : recipients) {
            int success = gateway.send(dto.getInstitutionalEmail(), "UniNa Library - Notification", message);
            if (success != 200) {
                throw new RuntimeException(
                        "Email delivery failed for " + dto.getInstitutionalEmail() + " (code " + success + ")");
            }
        }
    }
}
