        return LibraryFacade.getInstance().makeReservation(
                new ReservationRequestDTO(roomId, areaId, seatId, date, timeSlotId, studentId));
    }

    /**
     */
    @PutMapping("/{reservationId}/cancel")
    public void cancelReservation(@PathVariable("reservationId") Long reservationId,
                                    @RequestParam("studentId") Long studentId) {
        LibraryFacade.getInstance().cancelReservation(reservationId, studentId);
    }

    /**
     */
    @PutMapping("/{reservationId}/checkIn")
    public void performCheckIn(@PathVariable("reservationId") Long reservationId,
                                @RequestParam("studentId") Long studentId) {
        LibraryFacade.getInstance().performCheckIn(reservationId, studentId);
    }
}
